#!/usr/bin/env node
// Shipshape plank join and verification-conformance check.
//
// Default mode joins every plank annotation on a production seam to a current step-definition
// pattern, and joins each pattern to the scenarios that bind it. It reddens where a behaviour-
// bearing seam carries no plank, where a plank matches no current pattern, where a plank sits
// outside a docblock on a declaration, or where a provisional plank names a scenario that no
// longer carries @captain.
//
// `--conformance` mode discharges the verification-conformance rule set in
// scantlings/verification-conformance.json against the verification support directories.

import fs from 'node:fs';
import path from 'node:path';
import { parse } from 'acorn';

const ROOT = path.resolve(import.meta.dirname, '..');
const IMPLEMENTATION = ['js'];
const SPECS = ['features'];
const VERIFICATION = ['features/steps', 'features/support'];
const RULESET = 'scantlings/verification-conformance.json';

const failures = [];
const fail = (message) => failures.push(message);

function walkFiles(dir, extension) {
  const absolute = path.join(ROOT, dir);
  if (!fs.existsSync(absolute)) return [];
  const found = [];
  for (const entry of fs.readdirSync(absolute, { withFileTypes: true })) {
    const relative = path.join(dir, entry.name);
    if (entry.isDirectory()) found.push(...walkFiles(relative, extension));
    else if (entry.name.endsWith(extension)) found.push(relative);
  }
  return found;
}

// ---------------------------------------------------------------- step definitions

const KEYWORDS = ['Given', 'When', 'Then'];

function stepDefinitionPatterns() {
  const patterns = [];
  for (const file of VERIFICATION.flatMap((dir) => walkFiles(dir, '.js'))) {
    const source = fs.readFileSync(path.join(ROOT, file), 'utf8');
    for (const keyword of KEYWORDS) {
      const finder = new RegExp(`\\b${keyword}\\s*\\(\\s*(['"\`])([\\s\\S]*?)\\1`, 'g');
      let match = finder.exec(source);
      while (match) {
        patterns.push({ keyword, pattern: match[2], file });
        match = finder.exec(source);
      }
    }
  }
  return patterns;
}

function expressionToRegExp(expression) {
  let out = '';
  for (let index = 0; index < expression.length; index += 1) {
    const rest = expression.slice(index);
    const parameter = /^\{(string|int|float|word|)\}/.exec(rest);
    if (parameter) {
      out +=
        parameter[1] === 'int'
          ? '(-?\\d+)'
          : parameter[1] === 'float'
            ? '(-?\\d+(?:\\.\\d+)?)'
            : parameter[1] === 'word'
              ? '(\\S+)'
              : '(?:"([^"]*)"|(\\S+))';
      index += parameter[0].length - 1;
      continue;
    }
    out += /[.*+?^${}()|[\]\\]/.test(expression[index]) ? `\\${expression[index]}` : expression[index];
  }
  return new RegExp(`^${out}$`);
}

// ---------------------------------------------------------------- specs

function readScenarios() {
  const scenarios = [];
  for (const file of SPECS.flatMap((dir) => walkFiles(dir, '.feature'))) {
    const lines = fs.readFileSync(path.join(ROOT, file), 'utf8').split('\n');
    let current = null;
    let tags = [];
    let keyword = 'Given';
    for (const line of lines) {
      const text = line.trim();
      if (text.startsWith('@')) {
        tags = text.split(/\s+/);
        continue;
      }
      const heading = /^(Scenario Outline|Scenario|Example):\s*(.+)$/.exec(text);
      if (heading) {
        current = { reference: `${file}:${heading[2].trim()}`, tags, steps: [] };
        scenarios.push(current);
        tags = [];
        continue;
      }
      if (/^(Feature|Rule|Background):/.test(text)) {
        current = null;
        tags = [];
        continue;
      }
      const step = /^(Given|When|Then|And|But)\s+(.+)$/.exec(text);
      if (step && current) {
        if (KEYWORDS.includes(step[1])) keyword = step[1];
        current.steps.push({ keyword, text: step[2].trim() });
      }
    }
  }
  return scenarios;
}

// ---------------------------------------------------------------- planks

const PLANK_TOKEN = /@planks(-provisional)?\s*\(\s*(['"])([\s\S]*?)\2\s*\)/;

function collectPlanks() {
  const planks = [];
  for (const file of IMPLEMENTATION.flatMap((dir) => walkFiles(dir, '.js'))) {
    const source = fs.readFileSync(path.join(ROOT, file), 'utf8');
    const comments = [];
    let tree;
    try {
      tree = parse(source, {
        ecmaVersion: 'latest',
        sourceType: 'script',
        locations: true,
        onComment: comments,
      });
    } catch (error) {
      fail(`${file}: does not parse (${error.message})`);
      continue;
    }

    const docblocks = comments.filter((c) => c.type === 'Block' && c.value.startsWith('*'));
    for (const comment of comments) {
      if (docblocks.includes(comment)) continue;
      if (PLANK_TOKEN.test(comment.value))
        fail(`${file}:${comment.loc.start.line}: plank outside a docblock is malformed`);
    }

    const seams = [];
    (function visit(node, top) {
      if (!node || typeof node.type !== 'string') return;
      const named =
        (node.type === 'FunctionDeclaration' && node.id) ||
        (node.type === 'ClassDeclaration' && node.id) ||
        (node.type === 'MethodDefinition' && node.key);
      if (named) seams.push({ node: top ?? node, name: node.id ? node.id.name : node.key.name ?? 'method' });
      if (node.type === 'VariableDeclaration') {
        for (const declarator of node.declarations) {
          const init = declarator.init;
          if (init && (init.type === 'FunctionExpression' || init.type === 'ArrowFunctionExpression'))
            seams.push({ node, name: declarator.id.name ?? 'function' });
        }
      }
      for (const key of Object.keys(node)) {
        const value = node[key];
        if (Array.isArray(value)) for (const child of value) visit(child, null);
        else if (value && typeof value.type === 'string') visit(value, null);
      }
    })(tree, null);

    for (const seam of seams) {
      const preceding = docblocks
        .filter((c) => c.end <= seam.node.start && source.slice(c.end, seam.node.start).trim() === '')
        .pop();
      const match = preceding ? PLANK_TOKEN.exec(preceding.value) : null;
      if (!match) {
        fail(`${file}:${seam.node.loc.start.line}: seam "${seam.name}" carries no plank`);
        continue;
      }
      const all = preceding.value.matchAll(new RegExp(PLANK_TOKEN, 'g'));
      for (const one of all)
        planks.push({
          file,
          line: seam.node.loc.start.line,
          seam: seam.name,
          provisional: Boolean(one[1]),
          value: one[3],
        });
    }
  }
  return planks;
}

// ---------------------------------------------------------------- conformance rule set

function conformance() {
  const rulesetPath = path.join(ROOT, RULESET);
  if (!fs.existsSync(rulesetPath)) {
    fail(`${RULESET}: rule set is missing`);
    return;
  }
  const { rules } = JSON.parse(fs.readFileSync(rulesetPath, 'utf8'));
  const files = VERIFICATION.flatMap((dir) => walkFiles(dir, '.js'));
  console.log(`verification-conformance: ${rules.length} rules over ${files.length} files`);
  for (const file of files) {
    const lines = fs.readFileSync(path.join(ROOT, file), 'utf8').split('\n');
    for (const rule of rules) {
      const finder = new RegExp(rule.pattern);
      lines.forEach((line, index) => {
        if (!finder.test(line)) return;
        const window = lines.slice(Math.max(0, index - 3), index + 1).join('\n');
        if (rule.exemption && new RegExp(rule.exemption).test(window)) return;
        fail(`${file}:${index + 1}: ${rule.id}: ${rule.message}`);
      });
    }
  }
}

// ---------------------------------------------------------------- join

function join() {
  const patterns = stepDefinitionPatterns();
  const scenarios = readScenarios();
  const live = scenarios.filter((s) => !s.tags.includes('@captain') && !s.tags.includes('@shipwright'));

  console.log(`step definitions: ${patterns.length}`);
  for (const definition of patterns) {
    const matcher = expressionToRegExp(definition.pattern);
    const bound = live
      .filter((s) => s.steps.some((step) => step.keyword === definition.keyword && matcher.test(step.text)))
      .map((s) => s.reference);
    console.log(`  ${definition.keyword} ${definition.pattern} -> ${bound.length ? bound.join(', ') : 'no scenario'}`);
  }

  const planks = collectPlanks();
  console.log(`planks: ${planks.length}`);
  const patternStrings = new Set(patterns.map((p) => p.pattern));
  const captainScenarios = new Set(
    scenarios.filter((s) => s.tags.includes('@captain')).map((s) => s.reference),
  );
  for (const plank of planks) {
    console.log(`  ${plank.file}:${plank.line} ${plank.seam} -> ${plank.value}`);
    if (plank.provisional) {
      if (!captainScenarios.has(plank.value))
        fail(`${plank.file}:${plank.line}: provisional plank names no @captain scenario: ${plank.value}`);
      continue;
    }
    if (!patternStrings.has(plank.value))
      fail(`${plank.file}:${plank.line}: plank matches no current step-definition pattern: ${plank.value}`);
  }
}

if (process.argv.includes('--conformance')) conformance();
else join();

if (failures.length) {
  console.error(`\nplank-join: ${failures.length} failure(s)`);
  for (const failure of failures) console.error(`  ${failure}`);
  process.exit(1);
}
console.log('\nplank-join: clean');

{
